package cn.mop.persistence;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.sql.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
/** Actual restricted runtime on the approved database. All synthetic rows remain in a rolled-back transaction. */
@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresContactImportSchemaIntegrationTest {
    static HikariDataSource pool;Connection c;String actor;static final String TENANT="55000000-0000-4000-8000-000000000001";
    @BeforeAll static void connect(){String url=System.getenv("SPRING_DATASOURCE_URL");assertNotNull(url);assertTrue(url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));assertEquals("mop_test_runtime",System.getenv("SPRING_DATASOURCE_USERNAME"));var config=new HikariConfig();config.setJdbcUrl(url);config.setUsername(System.getenv("SPRING_DATASOURCE_USERNAME"));config.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));config.setMaximumPoolSize(2);config.setConnectionTimeout(5000);pool=new HikariDataSource(config);}
    @BeforeEach void begin()throws Exception{c=pool.getConnection();c.setAutoCommit(false);actor=scalar("SELECT user_id::text FROM public.mop_membership WHERE tenant_id='"+TENANT+"' AND role_code='padmin' AND active ORDER BY user_id LIMIT 1");}
    @AfterEach void rollback()throws Exception{if(c!=null){c.rollback();c.close();}}
    @AfterAll static void close(){if(pool!=null)pool.close();}
    void sql(String value)throws SQLException{try(var s=c.createStatement()){s.execute(value);}}
    String scalar(String value)throws SQLException{try(var s=c.createStatement();var rows=s.executeQuery(value)){assertTrue(rows.next());return rows.getString(1);}}
    @FunctionalInterface interface Action{void run()throws SQLException;}
    void rejected(String state,Action action)throws SQLException{Savepoint point=c.setSavepoint();SQLException failure=assertThrows(SQLException.class,action::run);assertEquals(state,failure.getSQLState());c.rollback(point);c.releaseSavepoint(point);}
    void validate()throws SQLException{sql("SET CONSTRAINTS ALL IMMEDIATE");sql("SET CONSTRAINTS ALL DEFERRED");}
    String job(int rows)throws SQLException{String id=UUID.randomUUID().toString();String payload="{\"rows\":["+String.join(",",Collections.nCopies(Math.max(1,Math.min(rows,100)),"{\"name\":\"SYNTHETIC_SCHEMA\",\"roles\":[\"REPORTER\"],\"mobile\":null,\"email\":null,\"wecom_user_id\":null,\"preferred_priorities\":null,\"quiet_window\":null,\"enabled\":false}"))+"]}";try(var s=c.prepareStatement("INSERT INTO public.mop_contact_import_job(id,tenant_id,created_by,permission_version,row_count,payload_bytes,trace_id) VALUES (?::uuid,?::uuid,?::uuid,1,?,?,?)")){s.setString(1,id);s.setString(2,TENANT);s.setString(3,actor);s.setInt(4,rows);s.setBytes(5,payload.getBytes(StandardCharsets.UTF_8));s.setString(6,UUID.randomUUID().toString());s.executeUpdate();}return id;}
    void claim(String id,String duration)throws SQLException{sql("UPDATE public.mop_contact_import_job SET state='LEASED',attempts=attempts+1,fencing_token=fencing_token+1,lease_owner='schema-worker',lease_started_at=clock_timestamp()::timestamptz(3),lease_until=clock_timestamp()::timestamptz(3)+interval '"+duration+"',next_at=NULL,error_code=NULL,version=version+1,updated_at=clock_timestamp() WHERE id='"+id+"'");}
    void finish(String id)throws SQLException{sql("UPDATE public.mop_contact_import_job SET state='SUCCEEDED',lease_owner=NULL,lease_started_at=NULL,lease_until=NULL,next_at=NULL,completed_rows=row_count,error_code=NULL,version=version+1,updated_at=clock_timestamp() WHERE id='"+id+"'");}
    void fail(String id)throws SQLException{sql("UPDATE public.mop_contact_import_job SET state='FAILED',lease_owner=NULL,lease_started_at=NULL,lease_until=NULL,next_at=NULL,completed_rows=NULL,error_code='PAYLOAD_INVALID',version=version+1,updated_at=clock_timestamp() WHERE id='"+id+"'");}
    String contact()throws SQLException{String id=UUID.randomUUID().toString();sql("INSERT INTO public.mop_customer_contact(id,tenant_id,created_by) VALUES ('"+id+"','"+TENANT+"','"+actor+"')");sql("INSERT INTO public.mop_customer_contact_revision(tenant_id,contact_id,version,recorded_by,action,name,roles,enabled) VALUES ('"+TENANT+"','"+id+"',1,'"+actor+"','CREATE','SYNTHETIC_SCHEMA_IMPORT',ARRAY['DECISION_MAKER'],true)");return id;}
    void result(String id,int number,int count,String contact)throws SQLException{sql("INSERT INTO public.mop_contact_import_result(tenant_id,job_id,row_number,row_count,contact_id) VALUES ('"+TENANT+"','"+id+"',"+number+","+count+",'"+contact+"')");}
    @Test void runtimeSchemaMetadataFunctionsAndNarrowPermissionsVerified()throws Exception{assertEquals("mop_test_runtime",scalar("SELECT current_user"));TestSchemaMigration.verifyContactImports(c);for(String fn:List.of("mop_contact_import_transition_guard","mop_contact_import_completion_guard")){assertEquals("false",scalar("SELECT prosecdef::text FROM pg_proc WHERE oid='public."+fn+"()'::regprocedure"));assertEquals("0",scalar("SELECT count(*) FROM pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a WHERE p.oid='public."+fn+"()'::regprocedure AND a.grantee=0"));}}
    @Test void acceptanceIsPendingWithGeneratedHashAndNoResult()throws Exception{String id=job(2);validate();assertEquals("PENDING|0|0|1",scalar("SELECT state||'|'||attempts||'|'||fencing_token||'|'||version FROM public.mop_contact_import_job WHERE id='"+id+"'"));try(var s=c.createStatement();var r=s.executeQuery("SELECT payload_bytes,input_sha256 FROM public.mop_contact_import_job WHERE id='"+id+"'")){assertTrue(r.next());assertEquals(HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(r.getBytes(1))),r.getString(2));}assertEquals("0",scalar("SELECT count(*) FROM public.mop_contact_import_result WHERE job_id='"+id+"'"));}
    @Test void inputCountAndScopeConstraintsRejectInvalidAcceptance()throws Exception{for(int rows:new int[]{0,101})rejected("23514",()->job(rows));rejected("23503",()->sql("INSERT INTO public.mop_contact_import_job(id,tenant_id,created_by,permission_version,row_count,payload_bytes,trace_id) VALUES (gen_random_uuid(),gen_random_uuid(),'"+actor+"',1,1,'{}'::bytea,'test')"));String foreign=scalar("SELECT m.user_id::text FROM public.mop_membership m WHERE NOT EXISTS(SELECT 1 FROM public.mop_membership a WHERE a.user_id=m.user_id AND a.tenant_id='"+TENANT+"') LIMIT 1");rejected("23503",()->sql("INSERT INTO public.mop_contact_import_job(id,tenant_id,created_by,permission_version,row_count,payload_bytes,trace_id) VALUES (gen_random_uuid(),'"+TENANT+"','"+foreign+"',1,1,'{}'::bytea,'test')"));}
    @Test void acceptanceCannotStartAlreadyLeasedOrSucceeded()throws Exception{for(String state:List.of("LEASED","SUCCEEDED","FAILED"))rejected("23514",()->sql("INSERT INTO public.mop_contact_import_job(id,tenant_id,created_by,permission_version,row_count,payload_bytes,trace_id,state,attempts,fencing_token,version) VALUES (gen_random_uuid(),'"+TENANT+"','"+actor+"',1,1,'{}'::bytea,'test','"+state+"',1,1,2)"));}
    @Test void normalClaimIsFencedAndActiveLeaseCannotBeStolen()throws Exception{String id=job(1);String hash=scalar("SELECT input_sha256 FROM public.mop_contact_import_job WHERE id='"+id+"'");claim(id,"30 seconds");validate();assertEquals(hash,scalar("SELECT input_sha256 FROM public.mop_contact_import_job WHERE id='"+id+"'"));assertEquals("LEASED|1|1|2",scalar("SELECT state||'|'||attempts||'|'||fencing_token||'|'||version FROM public.mop_contact_import_job WHERE id='"+id+"'"));rejected("23514",()->claim(id,"30 seconds"));}
    @Test void changedFenceOrMissingVersionIncrementRejected()throws Exception{String id=job(1);claim(id,"30 seconds");rejected("23514",()->sql("UPDATE public.mop_contact_import_job SET state='FAILED',lease_owner=NULL,lease_started_at=NULL,lease_until=NULL,error_code='PAYLOAD_INVALID' WHERE id='"+id+"'"));rejected("23514",()->sql("UPDATE public.mop_contact_import_job SET fencing_token=fencing_token+1,version=version+1 WHERE id='"+id+"'"));}
    @Test void retryRequiresExplicitFutureTimeAndNonNullTransientError()throws Exception{String id=job(1);claim(id,"30 seconds");String prefix="UPDATE public.mop_contact_import_job SET state='PENDING',lease_owner=NULL,lease_started_at=NULL,lease_until=NULL,version=version+1,updated_at=clock_timestamp(),";rejected("23514",()->sql(prefix+"next_at=clock_timestamp(),error_code='UPSTREAM_UNAVAILABLE' WHERE id='"+id+"'"));rejected("23514",()->sql(prefix+"next_at=clock_timestamp()+interval '30 seconds',error_code=NULL WHERE id='"+id+"'"));sql(prefix+"next_at=clock_timestamp()+interval '30 seconds',error_code='UPSTREAM_UNAVAILABLE' WHERE id='"+id+"'");validate();rejected("23514",()->claim(id,"30 seconds"));}
    @Test void expiredLeaseRejectsCompletionAndCanBeReclaimedWithHigherFence()throws Exception{String id=job(1);claim(id,"10 milliseconds");sql("SELECT pg_sleep(0.03)");rejected("23514",()->fail(id));claim(id,"30 seconds");assertEquals("2",scalar("SELECT fencing_token FROM public.mop_contact_import_job WHERE id='"+id+"'"));fail(id);validate();}
    @Test void failedTerminalCannotBeReopenedOrAltered()throws Exception{String id=job(1);claim(id,"30 seconds");fail(id);validate();rejected("23514",()->sql("UPDATE public.mop_contact_import_job SET version=version+1,updated_at=clock_timestamp() WHERE id='"+id+"'"));rejected("23514",()->claim(id,"30 seconds"));}
    @Test void successRequiresEveryOriginalPositionAndImmutableRevisionReference()throws Exception{String id=job(2),a=contact(),b=contact();claim(id,"30 seconds");rejected("23514",()->{result(id,1,2,a);finish(id);validate();});result(id,1,2,a);result(id,2,2,b);finish(id);validate();assertEquals("SUCCEEDED|2",scalar("SELECT state||'|'||completed_rows FROM public.mop_contact_import_job WHERE id='"+id+"'"));rejected("23514",()->sql("UPDATE public.mop_contact_import_job SET version=version+1 WHERE id='"+id+"'"));}
    @Test void pendingJobCannotCommitResultRowsWithoutCompletion()throws Exception{String id=job(1),contact=contact();rejected("23514",()->{result(id,1,1,contact);validate();});assertEquals("0",scalar("SELECT count(*) FROM public.mop_contact_import_result WHERE job_id='"+id+"'"));}
    @Test void resultTenantCountPositionAndOriginalRevisionAreConstrained()throws Exception{String id=job(1),contact=contact();rejected("23503",()->result(id,1,2,contact));rejected("23514",()->result(id,0,1,contact));rejected("23514",()->result(id,2,1,contact));rejected("23503",()->result(id,1,1,UUID.randomUUID().toString()));rejected("23503",()->sql("INSERT INTO public.mop_contact_import_result(tenant_id,job_id,row_number,row_count,contact_id) VALUES ('55000000-0000-4000-8000-000000000002','"+id+"',1,1,'"+contact+"')"));}
    @Test void runtimeCannotRewritePayloadIdentityResultsOrDelete()throws Exception{for(String statement:List.of("UPDATE public.mop_contact_import_job SET payload_bytes='{}'::bytea WHERE false","UPDATE public.mop_contact_import_job SET created_by=gen_random_uuid() WHERE false","UPDATE public.mop_contact_import_job SET permission_version=2 WHERE false","UPDATE public.mop_contact_import_job SET row_count=2 WHERE false","UPDATE public.mop_contact_import_result SET contact_id=gen_random_uuid() WHERE false","DELETE FROM public.mop_contact_import_job WHERE false","DELETE FROM public.mop_contact_import_result WHERE false","TRUNCATE public.mop_contact_import_job"))rejected("42501",()->sql(statement));}
}
